import{_ as o,C as s,c as r,o as n,a3 as t,G as i}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Process an applicant","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/recruitment/applicants/process-applicant.md","filePath":"master/human-resources/recruitment/applicants/process-applicant.md","lastUpdated":1791902625000}'),l={name:"master/human-resources/recruitment/applicants/process-applicant.md"};function p(h,e,c,g,d,m){const a=s("ImagePopup");return n(),r("div",null,[e[0]||(e[0]=t('<h1 id="process-an-applicant" tabindex="-1">Process an applicant <a class="header-anchor" href="#process-an-applicant" aria-label="Permalink to &quot;Process an applicant&quot;">​</a></h1><p>The applicant page is where you do the hiring work. You move the person through stages, rate them, assign people to the application, record salary and notes, and finally hire them. Everything happens on one page, in the <strong>View Applicant</strong> and <strong>Edit Applicant</strong> modes.</p><blockquote><p><strong>In simple words:</strong> Open the applicant, fill in the details, click the stages as the person progresses, and create the employee when they sign.</p></blockquote><p>Open <code>Recruitments → Applications → Applicants</code> and click an applicant. <strong>View</strong> shows the record. Click <strong>Edit</strong> to change it, then <strong>Save changes</strong>.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>The applicant exists. See <a href="./add-applicant.html">Add an applicant</a>.</li><li>The <a href="./../job-positions/job-positions.html">job position</a>, <a href="./../setup/stages.html">stages</a>, <a href="./../setup/tags-degrees.html">tags and degrees</a> and <a href="./../setup/sources-and-mediums.html">sources and mediums</a> you want to choose are created.</li></ul></div><h2 id="worked-example" tabindex="-1">Worked example <a class="header-anchor" href="#worked-example" aria-label="Permalink to &quot;Worked example&quot;">​</a></h2><p>Rahul Verma applies for <strong>Warehouse Supervisor</strong>. You follow him from <strong>New</strong> to hired.</p><h3 id="details-you-fill-in" tabindex="-1">Details you fill in <a class="header-anchor" href="#details-you-fill-in" aria-label="Permalink to &quot;Details you fill in&quot;">​</a></h3><ol><li>Open Rahul&#39;s applicant page in edit mode. The <strong>New</strong> stage is blue on the stage bar.</li></ol><ol start="2"><li>In <strong>General Information</strong>, choose <strong>Warehouse Supervisor</strong> in <strong>Job Positions</strong>.</li><li>Set <strong>Recruiter</strong> to <strong>ERP Admin</strong>. Add an <strong>Interviewer</strong>. Add one or more <strong>Tags</strong>.</li></ol><ul><li><strong><em>Candidate name:</em></strong> Required. Choose the candidate. <strong>Emails</strong>, <strong>Phone</strong> and <strong>Linkedin Profile</strong> load from the candidate.</li><li><strong><em>Job Positions:</em></strong> The job applied for. The first time you choose one, Aureus puts the applicant in the first default stage. Later changes copy the recruiter, interviewers and department from the position.</li><li><strong><em>Hired Date:</em></strong> Read only. It appears once the applicant is hired.</li><li><strong><em>Recruiter:</em></strong> The person who owns this application.</li><li><strong><em>Interviewer:</em></strong> One or more users who interview the person. You can create a user from the field.</li><li><strong><em>Tags:</em></strong> Labels such as skills or areas. If you leave it empty, Aureus shows the candidate&#39;s tags.</li><li><strong><em>Notes:</em></strong> A text box for your own remarks.</li></ul><ol start="4"><li>Use the right column. Choose a <strong>Degree</strong> and an <strong>Availability Date</strong> under <strong>Education &amp; Availability</strong>. Set <strong>Department</strong> if needed.</li></ol><ol start="5"><li>Under <strong>Expected &amp; Proposed Salary</strong>, type <code>40000</code> in <strong>Expected Salary</strong>. Fill <strong>Proposed Salary</strong> when you make an offer. Each salary has an <strong>Other Benefit</strong> field for extras. All values are numbers from 0.</li></ol>',13)),i(a,{src:"/images1/recruitment/applicant_salary.png",alt:"Expected and Proposed Salary card with Expected Salary 40000"}),e[1]||(e[1]=t('<ol start="6"><li>Under <strong>Source &amp; Medium</strong>, choose where the application came from, for example <strong>LinkedIn</strong> as <strong>Source</strong>. Choose how it reached you in <strong>Medium</strong>.</li></ol><ol start="7"><li>Click <strong>Save changes</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><strong>Degree</strong> and <strong>Availability Date</strong> are saved on the candidate. They show on every application of that person.</p></div><h3 id="rate-the-applicant" tabindex="-1">Rate the applicant <a class="header-anchor" href="#rate-the-applicant" aria-label="Permalink to &quot;Rate the applicant&quot;">​</a></h3><ol start="8"><li>Click the stars at the top of <strong>General Information</strong>. The tooltips are <strong>Good</strong>, <strong>Very Good</strong> and <strong>Very Excellent</strong>. Click the active star again to clear the rating.</li></ol><h3 id="move-through-the-stages" tabindex="-1">Move through the stages <a class="header-anchor" href="#move-through-the-stages" aria-label="Permalink to &quot;Move through the stages&quot;">​</a></h3><ol start="9"><li>Click the next stage on the bar, for example <strong>First Interview</strong>. The change saves at once. You can click any stage, forward or back.</li></ol><ol start="10"><li>Click the icon button <strong>State</strong>. Choose <strong>In Progress</strong>, <strong>Ready for next stage</strong> or <strong>Blocked</strong>, then click <strong>Submit</strong>.</li></ol><p>When you change the stage, the state goes back to <strong>In Progress</strong>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A <strong>Blocked</strong> applicant disappears from the main applicant list. Open the <strong>Blocked</strong> preset to find them. See <a href="./applicant-list.html">Applicant list</a>.</p></div><h3 id="hire-the-applicant" tabindex="-1">Hire the applicant <a class="header-anchor" href="#hire-the-applicant" aria-label="Permalink to &quot;Hire the applicant&quot;">​</a></h3><ol start="11"><li>Click <strong>Contract Signed</strong> on the stage bar. This stage is a <strong>Hired Stage</strong>. Aureus sets the <strong>Application status</strong> to <strong>Hired</strong> and fills <strong>Hired Date</strong>.</li></ol><ol start="12"><li>Click <strong>Create Employee</strong>. Aureus creates the employee from the applicant and opens the employee page. Check it and save. See <a href="./../../employees/employees/add-employee.html">Add an employee</a>.</li></ol><ol start="13"><li>Back on the applicant, click the <strong>Go to Employee</strong> icon to open the employee later.</li></ol><p>If you click another stage that is not a hired stage, the applicant is no longer hired.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>Create Employee:</strong> creates an employee from the applicant. It disappears once the applicant is hired or linked to an employee.</li><li><strong>Go to Employee:</strong> opens the linked employee. It replaces <strong>Create Employee</strong>.</li><li><strong>Refuse:</strong> turns the applicant down. See <a href="./refuse-and-reopen.html">Refuse and reopen</a>.</li><li><strong>Restore:</strong> brings a refused applicant back.</li><li><strong>Delete:</strong> removes the applicant after you confirm.</li><li><strong>Application status:</strong> <strong>Hired</strong>, <strong>Refused</strong> or <strong>Archived</strong>. An ongoing applicant shows no status.</li></ul><h2 id="chatter-and-activities" tabindex="-1">Chatter and activities <a class="header-anchor" href="#chatter-and-activities" aria-label="Permalink to &quot;Chatter and activities&quot;">​</a></h2><p>The chatter button in the header opens <strong>Chatter</strong> with <strong>Send Message</strong>, <strong>Log Note</strong> and <strong>Schedule Activity</strong>. Use it for talks with the team and follow-up tasks. The clock icon on a list row opens the same activity action. See <a href="./../../../getting-started/chatter/introduction.html">Chatter</a>, <a href="./../../../getting-started/chatter/actions/log-note.html">Log a note</a> and <a href="./../../../getting-started/chatter/actions/activity.html">Schedule an activity</a>.</p><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><p>The <strong>Skills</strong> table at the bottom of the <strong>View</strong> page lists the skills of the person. They come from the candidate. See <a href="./candidates.html#skills">Candidates</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./refuse-and-reopen.html">Refuse and reopen</a></li><li><a href="./applicant-list.html">Applicant list</a></li><li><a href="./../../employees/employees/add-employee.html">Add an employee</a></li><li><a href="./../setup/stages.html">Stages</a></li></ul>',23))])}const k=o(l,[["render",p]]);export{f as __pageData,k as default};
